import { id } from 'ethers';
import { miningGasBounds } from './mining-gas-profile.js';

// Site-supplied ceilings, not predictions of the gas charged. Keep enough
// room for cold storage and first-use branches without an RPC estimate on tap.
export const DEFAULT_TRANSACTION_GAS_LIMIT = 8_000_000n;
export const DEITY_TRANSACTION_GAS_LIMIT = 12_000_000n;
const MINE_SELECTOR = id('mineRun(uint32)').slice(0, 10);
const DEITY_SELECTOR = id('purchaseDeityPass(uint32,uint8,bytes32)').slice(0, 10);

export function fixedTransactionGasLimit(request = {}) {
  const selector = String(request.data ?? '').slice(0, 10).toLowerCase();
  if (selector === MINE_SELECTOR) return miningGasBounds().max;
  if (selector === DEITY_SELECTOR) return DEITY_TRANSACTION_GAS_LIMIT;
  return DEFAULT_TRANSACTION_GAS_LIMIT;
}

export function withFixedGasLimit(request) {
  return request?.gasLimit != null ? request : {
    ...request,
    gasLimit: fixedTransactionGasLimit(request),
  };
}
